7|const $ = s => document.querySelector(s);
8|const jour = s => new Date(String(s).slice(0, 10) + "T12:00:00");
9|const auj = () => { const d = new Date(); d.setHours(12, 0, 0, 0); return d; };
10|const ecart = s => Math.round((jour(s) - auj()) / 864e5);
11|const ic = (n, cls = "") => `<svg class="${cls}"><use href="#i-${n}"/></svg>`;
12|const esc = t => String(t ?? "").replace(/[&<>"]/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}[c]));
13|const lundi = d => { const x = new Date(d); x.setDate(x.getDate() - ((x.getDay() + 6) % 7)); return x; };
14|const cle = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
15|const moins = matchMedia("(prefers-reduced-motion: reduce)");
16|const api = () => window.pywebview && window.pywebview.api;
