18|function animerNombre(el, vers, fmt = n => n) {
19|  const de = Number(el.dataset.v ?? 0); el.dataset.v = vers;
20|  if (moins.matches || de === vers) { el.textContent = fmt(vers); return; }
21|  const t0 = performance.now(), d = 650;
22|  const pas = t => { const k = Math.min(1, Math.max(0, (t - t0) / d)), e = 1 - Math.pow(1 - k, 3);
23|    if (el.dataset.v == vers) el.textContent = fmt(Math.round(de + (vers - de) * e)); if (k < 1) requestAnimationFrame(pas); };
24|  requestAnimationFrame(pas);
