/* =====================================================================  U5 : carte de preparation, reglages, theme */
/* Les huit classes ecrites par U4, qui n'avaient aucune regle visible. Aucune couleur en dur : les
   variables de la feuille portent les deux themes, et les contrastes sont ceux du bloc des textes. */
.tx-carte-nombres, .tx-preparer-nombres { margin-top: 10px; font-size: 13.5px; font-weight: 600; color: var(--texte); }
.tx-carte-moteur { margin-top: 10px; padding: 8px 12px; border-radius: 8px; color: var(--alerte);
  background: var(--alerte-doux); border: 1px solid color-mix(in srgb, var(--alerte-icone) 45%, transparent); }
.tx-carte-travail { display: flex; flex-direction: column; gap: 2px; margin-top: 10px; padding: 10px 12px;
  border: 1px solid var(--bord); border-radius: var(--rayon); background: var(--surface); }
.tx-carte-travail p { margin: 0; }
.tx-carte-document { font-weight: 600; color: var(--texte); overflow-wrap: anywhere; }
.tx-carte-rang, .tx-carte-page { font-size: 12.5px; color: var(--texte-2); }
.tx-carte-pause { padding: 6px 10px; border-radius: 8px; color: var(--alerte); background: var(--alerte-doux);
  font-size: 12.5px; }

/* Deux boutons principaux dans la meme rangee quand le moteur manque et qu'une file attend (decision de
   U5) : Installer reste le bouton principal, Reprendre redevient un bouton ordinaire. */
.tx-carte .ligne-champ:has([data-action="installer"]:not([hidden])) [data-action="reprendre"] {
  background: var(--carte); border-color: var(--bord-fort); color: var(--texte);
}

/* La ligne de resultat s'ouvre au clavier (ecart 195) : meme anneau de focus que les lectures. */
.tx-trouve:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

