def regle(css, selecteur):
    """Regle CSS dont le selecteur commence une ligne (jusqu'a l'accolade fermante), ou ''."""
    for m in re.finditer(re.escape(selecteur), css):
        debut = css.rfind("\n", 0, m.start()) + 1
        if css[debut:m.start()].strip():
            continue
        j = css.find("{", m.end())
        fin = css.find("}", j) if j >= 0 else -1
        if j < 0 or fin < 0:
            continue
        return css[debut:fin + 1]
    return ""

